//! Static glyph datasets with Unicode-name and localized keyword search.
//!
//! Two datasets ship in the binary: the complete fully-qualified RGI emoji set
//! for the pinned Unicode Emoji version (3,963 sequences for Emoji 18.0) and
//! 1,073 symbols. Both are generated by `tools/glyph-generator/generate.py`
//! from the official Unicode data files plus CLDR annotations; the generated
//! JSON is embedded with `include_str!`, so there is no runtime file access,
//! no parsing of external formats, and no network dependency.
//!
//! Search runs over the Unicode name, the CLDR English keywords, the curated
//! overrides, and - when Indonesian is an active language - the CLDR Indonesian
//! keywords. The dictionary in `data/glyphs/i18n.json` additionally expands
//! everyday words such as "sedih" into English tokens, so adding a language
//! stays a data-only change.
//!
//! Skin-tone variants are part of the dataset, not synthesised at render time:
//! every variant carries its exact RGI sequence, its tone list, and a link back
//! to the base glyph. The UI asks [`GlyphIndex::tone_variants`] what to show
//! instead of guessing from code-point ranges, which produced invalid
//! sequences for multi-person emoji.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

pub static EMOJIS_RAW: &str = include_str!("../../../data/glyphs/emojis.json");
pub static SYMBOLS_RAW: &str = include_str!("../../../data/glyphs/symbols.json");
pub static I18N_RAW: &str = include_str!("../../../data/glyphs/i18n.json");
pub static META_RAW: &str = include_str!("../../../data/glyphs/glyph-meta.json");

/// One glyph. Keys stay short because the dataset is embedded verbatim.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RawGlyph {
    #[serde(rename = "c")]
    pub char: String,
    /// Unicode/CLDR name. Empty on a variant means "base name + tone suffix".
    #[serde(rename = "n", default)]
    pub name: String,
    #[serde(rename = "g", default)]
    pub group: usize,
    /// English and curated search words. On a variant this holds only the
    /// words that are not inherited from the base glyph and tone vocabulary.
    #[serde(rename = "k", default)]
    pub keywords: String,
    /// Indonesian search words, matched only when `id` is an active language.
    #[serde(rename = "ki", default)]
    pub keywords_id: String,
    #[serde(rename = "t", default)]
    pub tone: usize,
    /// Subgroup index into [`GlyphMeta::subgroups`].
    #[serde(rename = "sg", default)]
    pub subgroup: Option<usize>,
    /// Base glyph this sequence is a variant of, when Unicode defines one.
    #[serde(rename = "v", default)]
    pub variant_of: Option<String>,
    /// `tone`, `gender`, `family`, `couple`, `flag`, or `zwj`.
    #[serde(rename = "vt", default)]
    pub variant_type: Option<String>,
    /// Skin tones applied to this sequence, in sequence order (1..=5).
    #[serde(rename = "tn", default)]
    pub tones: Vec<u8>,
    /// Derived uppercase code points, e.g. `1F44B` or `1F469 200D 1F91D ...`.
    #[serde(skip)]
    pub codepoints: String,
}

impl RawGlyph {
    pub fn is_tone_variant(&self) -> bool {
        !self.tones.is_empty()
    }
}

/// Localized aliases keyed by language, then by the user-facing word.
pub type I18nMap = HashMap<String, HashMap<String, Vec<String>>>;

#[derive(Debug, Clone, Deserialize)]
pub struct MetaSubgroup {
    pub id: usize,
    pub g: usize,
    pub name: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct MetaTone {
    pub n: u8,
    pub en: String,
    pub id: String,
}

#[derive(Debug, Clone, Default, Deserialize)]
pub struct MetaCounts {
    #[serde(default)]
    pub entries: usize,
    #[serde(default)]
    pub bases: usize,
    #[serde(default)]
    pub tone_variants: usize,
    #[serde(default)]
    pub tone_bases: usize,
    #[serde(default)]
    pub zwj: usize,
    #[serde(default)]
    pub flags: usize,
    #[serde(default)]
    pub multi_tone: usize,
}

#[derive(Debug, Clone, Deserialize)]
pub struct MetaSource {
    pub file: String,
    pub version: String,
    pub sha256: String,
}

/// Dataset provenance, groups, subgroups and tone vocabulary.
#[derive(Debug, Clone, Deserialize, Default)]
pub struct GlyphMeta {
    pub schema: u32,
    pub unicode_emoji_version: String,
    pub cldr_version: String,
    pub groups: Vec<String>,
    pub subgroups: Vec<MetaSubgroup>,
    pub tones: Vec<MetaTone>,
    #[serde(default)]
    pub counts: MetaCounts,
    #[serde(default)]
    pub sources: Vec<MetaSource>,
}

/// Tone vocabulary: per tone number the English and Indonesian words, plus the
/// canonical English phrase used when composing variant names.
pub struct ToneVocab {
    en: HashMap<u8, Vec<String>>,
    id: HashMap<u8, Vec<String>>,
    names: HashMap<u8, String>,
}

pub struct GlyphIndex {
    emojis: Vec<RawGlyph>,
    symbols: Vec<RawGlyph>,
    i18n: I18nMap,
    meta: GlyphMeta,
    /// base sequence -> indices of its tone variants, ordered by tone tuple
    variants: HashMap<String, Vec<usize>>,
    /// indices of every glyph without a tone modifier, in dataset order
    base_indices: Vec<usize>,
    /// every symbol index; symbols never carry tone variants
    symbol_indices: Vec<usize>,
    /// concatenated hex code points -> index, for direct Unicode lookup
    point_emoji: HashMap<String, usize>,
    point_symbol: HashMap<String, usize>,
    tones: ToneVocab,
    base_count: usize,
}

/// A parsed query: the raw normalized text, per-token expansions, and an
/// optional canonical code-point form for direct Unicode lookup.
struct Query {
    raw: String,
    tokens: Vec<Vec<String>>,
    codepoints: Option<String>,
    /// Indonesian keywords only participate when `id` is an active language.
    use_id: bool,
}

impl GlyphIndex {
    pub fn load_embedded() -> Self {
        let mut emojis: Vec<RawGlyph> =
            serde_json::from_str(EMOJIS_RAW).expect("embedded emoji dataset is invalid");
        let mut symbols: Vec<RawGlyph> =
            serde_json::from_str(SYMBOLS_RAW).expect("embedded symbol dataset is invalid");
        let i18n: I18nMap =
            serde_json::from_str(I18N_RAW).expect("embedded i18n dictionary is invalid");
        let meta: GlyphMeta =
            serde_json::from_str(META_RAW).expect("embedded glyph metadata is invalid");

        for glyph in emojis.iter_mut().chain(symbols.iter_mut()) {
            glyph.codepoints = codepoints_of(&glyph.char);
        }

        let mut tones = ToneVocab {
            en: HashMap::new(),
            id: HashMap::new(),
            names: HashMap::new(),
        };
        for tone in &meta.tones {
            tones.names.insert(tone.n, tone.en.clone());
            tones.en.insert(tone.n, split_words(&tone.en));
            tones.id.insert(tone.n, split_words(&tone.id));
        }

        resolve_variants(&mut emojis, &tones);

        let mut variants: HashMap<String, Vec<usize>> = HashMap::new();
        for (i, glyph) in emojis.iter().enumerate() {
            if let Some(base) = &glyph.variant_of {
                variants.entry(base.clone()).or_default().push(i);
            }
        }
        for list in variants.values_mut() {
            list.sort_by(|&a, &b| {
                emojis[a]
                    .tones
                    .cmp(&emojis[b].tones)
                    .then_with(|| emojis[a].char.cmp(&emojis[b].char))
            });
        }
        let base_indices: Vec<usize> = emojis
            .iter()
            .enumerate()
            .filter(|(_, g)| g.tones.is_empty())
            .map(|(i, _)| i)
            .collect();
        let base_count = base_indices.len();
        let symbol_indices: Vec<usize> = (0..symbols.len()).collect();
        let mut point_emoji: HashMap<String, usize> = HashMap::new();
        for (i, glyph) in emojis.iter().enumerate() {
            point_emoji
                .entry(glyph.codepoints.replace(' ', ""))
                .or_insert(i);
        }
        let mut point_symbol: HashMap<String, usize> = HashMap::new();
        for (i, glyph) in symbols.iter().enumerate() {
            point_symbol
                .entry(glyph.codepoints.replace(' ', ""))
                .or_insert(i);
        }

        Self {
            emojis,
            symbols,
            i18n,
            meta,
            variants,
            base_indices,
            symbol_indices,
            point_emoji,
            point_symbol,
            tones,
            base_count,
        }
    }

    pub fn emoji_count(&self) -> usize {
        self.emojis.len()
    }

    /// Every emoji entry, base and tone variant, in dataset order. The browse
    /// grid uses [`Self::search`] instead; this is for introspection and tests.
    pub fn all_emojis(&self) -> &[RawGlyph] {
        &self.emojis
    }

    pub fn symbol_count(&self) -> usize {
        self.symbols.len()
    }

    /// Glyphs the browser shows before a search: every sequence without a
    /// skin-tone modifier. Tone variants are reachable through the popover and
    /// through tone-aware search.
    pub fn emoji_base_count(&self) -> usize {
        self.base_count
    }

    pub fn tone_variant_count(&self) -> usize {
        self.emojis.len() - self.base_count
    }

    pub fn meta(&self) -> &GlyphMeta {
        &self.meta
    }

    pub fn unicode_version(&self) -> &str {
        &self.meta.unicode_emoji_version
    }

    pub fn group_name(&self, group: usize) -> Option<&str> {
        self.meta.groups.get(group).map(|s| s.as_str())
    }

    pub fn subgroup_name(&self, subgroup: usize) -> Option<&str> {
        self.meta
            .subgroups
            .iter()
            .find(|s| s.id == subgroup)
            .map(|s| s.name.as_str())
    }

    /// Languages present in the bundled dictionary, for the About/preferences UI.
    pub fn available_languages(&self) -> Vec<String> {
        let mut langs: Vec<String> = self.i18n.keys().cloned().collect();
        langs.sort();
        langs
    }

    /// Exact RGI skin-tone variants of `base`, ordered light to dark.
    pub fn tone_variants(&self, base: &str) -> Vec<&RawGlyph> {
        match self.variants.get(base) {
            Some(list) => list.iter().map(|&i| &self.emojis[i]).collect(),
            None => Vec::new(),
        }
    }

    pub fn has_tone_variants(&self, glyph: &str) -> bool {
        self.variants.contains_key(glyph)
    }

    fn source(&self, tab: &str) -> &[RawGlyph] {
        match tab {
            "emoji" => &self.emojis,
            _ => &self.symbols,
        }
    }

    fn expand_token(&self, token: &str, langs: &[String]) -> Vec<String> {
        let mut out = vec![token.to_string()];
        for lang in langs {
            if let Some(dict) = self.i18n.get(lang) {
                if let Some(aliases) = dict.get(token) {
                    for alias in aliases {
                        let alias = alias.to_lowercase();
                        if !out.contains(&alias) {
                            out.push(alias);
                        }
                    }
                }
            }
        }
        out
    }

    fn matches(glyph: &RawGlyph, expansions: &[String], use_id: bool) -> bool {
        expansions.iter().any(|term| {
            !term.is_empty()
                && (glyph.name.contains(term.as_str())
                    || glyph.keywords.contains(term.as_str())
                    || (use_id && glyph.keywords_id.contains(term.as_str())))
        })
    }

    fn parse_query(&self, query: &str, langs: &str) -> Query {
        let raw = query.trim().to_lowercase();
        let stripped = raw.trim_matches(':').trim();
        let active_langs: Vec<String> = langs
            .split(',')
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .collect();
        let use_id = active_langs.iter().any(|l| l == "id");
        Query {
            tokens: stripped
                .split_whitespace()
                .map(|t| self.expand_token(t, &active_langs))
                .collect(),
            codepoints: hex_form(stripped),
            raw: stripped.to_string(),
            use_id,
        }
    }

    /// True when the query asks for skin tones, so tone variants join the
    /// result set instead of collapsing into their base glyph.
    fn tone_query(&self, query: &Query) -> bool {
        query.tokens.iter().flatten().any(|token| {
            self.tones
                .en
                .values()
                .chain(self.tones.id.values())
                .any(|words| words.iter().any(|w| w == token))
        })
    }

    fn score(&self, glyph: &RawGlyph, query: &Query) -> Option<u8> {
        if glyph.char == query.raw {
            return Some(0);
        }
        if let Some(cps) = &query.codepoints {
            if glyph.codepoints.replace(' ', "") == *cps {
                return Some(1);
            }
        }
        if glyph.name == query.raw {
            return Some(2);
        }
        if glyph.name.starts_with(&query.raw) {
            return Some(3);
        }
        if glyph.name.contains(&query.raw) {
            return Some(4);
        }
        if glyph.keywords.contains(&query.raw)
            || (query.use_id && glyph.keywords_id.contains(&query.raw))
        {
            return Some(5);
        }
        if query.tokens.iter().all(|e| Self::matches(glyph, e, query.use_id)) {
            return Some(6);
        }
        None
    }

    fn hits(&self, tab: &str, query: &str, langs: &str) -> Vec<usize> {
        let src = self.source(tab);
        let parsed = self.parse_query(query, langs);
        if parsed.raw.is_empty() {
            return self.browse_indices(tab).to_vec();
        }

        if let Some(cps) = &parsed.codepoints {
            let table = match tab {
                "emoji" => &self.point_emoji,
                _ => &self.point_symbol,
            };
            return table.get(cps).copied().into_iter().collect();
        }

        let show_variants = self.tone_query(&parsed);
        let mut scored: Vec<(u8, usize)> = Vec::new();
        for (i, glyph) in src.iter().enumerate() {
            if glyph.is_tone_variant() && !show_variants {
                continue;
            }
            if let Some(score) = self.score(glyph, &parsed) {
                scored.push((score, i));
            }
        }
        scored.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
        scored.into_iter().map(|(_, i)| i).collect()
    }

    /// Indices the browser pages through for a tab: base glyphs only for emoji,
    /// every symbol for the symbol tab.
    fn browse_indices(&self, tab: &str) -> &[usize] {
        match tab {
            "emoji" => &self.base_indices,
            _ => &self.symbol_indices,
        }
    }

    /// Search one tab. An empty query pages the browsable dataset (base glyphs
    /// only). Results are ranked: exact glyph, exact code points, name prefix,
    /// name substring, keyword substring, then token matches.
    pub fn search(
        &self,
        tab: &str,
        query: &str,
        langs: &str,
        offset: usize,
        limit: usize,
    ) -> Vec<&RawGlyph> {
        let src = self.source(tab);
        if query.trim().trim_matches(':').trim().is_empty() {
            return self
                .browse_indices(tab)
                .iter()
                .skip(offset)
                .take(limit)
                .map(|&i| &src[i])
                .collect();
        }
        self.hits(tab, query, langs)
            .into_iter()
            .skip(offset)
            .take(limit)
            .map(|i| &src[i])
            .collect()
    }

    /// Total hits for a query, so the UI can stop paging. Uses the same ranking
    /// path as [`Self::search`] so the count always matches the pages.
    pub fn search_total(&self, tab: &str, query: &str, langs: &str) -> usize {
        if query.trim().trim_matches(':').trim().is_empty() {
            return self.browse_indices(tab).len();
        }
        self.hits(tab, query, langs).len()
    }
}

fn split_words(text: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for word in text.split_whitespace() {
        let word = word.to_lowercase();
        if !out.contains(&word) {
            out.push(word);
        }
    }
    out
}

/// Variant keyword lists are short (tens of words), so a linear duplicate check
/// beats allocating a set per glyph during index construction.
fn merge_keywords<'a>(parts: impl IntoIterator<Item = &'a str>) -> String {
    let mut seen: Vec<&'a str> = Vec::new();
    let mut out = String::new();
    for word in parts {
        if word.is_empty() || seen.contains(&word) {
            continue;
        }
        seen.push(word);
        if !out.is_empty() {
            out.push(' ');
        }
        out.push_str(word);
    }
    out
}

/// `waving hand: light skin tone` is derivable for every tone variant, and so
/// is the keyword set: the generator only stores words that are not already
/// inherited from the base glyph or from the tone vocabulary.
fn resolve_variants(emojis: &mut [RawGlyph], tones: &ToneVocab) {
    let mut positions: HashMap<String, usize> = HashMap::new();
    for (i, glyph) in emojis.iter().enumerate() {
        positions.insert(glyph.char.clone(), i);
    }

    let pending: Vec<(usize, String, Vec<u8>, String, String)> = emojis
        .iter()
        .enumerate()
        .filter_map(|(i, g)| {
            g.variant_of.as_ref().map(|base| {
                (
                    i,
                    base.clone(),
                    g.tones.clone(),
                    g.keywords.clone(),
                    g.keywords_id.clone(),
                )
            })
        })
        .collect();

    for (index, base, glyph_tones, extra_en, extra_id) in pending {
        let Some(&base_index) = positions.get(&base) else {
            continue;
        };
        let base_name = emojis[base_index].name.clone();
        let base_en = emojis[base_index].keywords.clone();
        let base_id = emojis[base_index].keywords_id.clone();

        if emojis[index].name.is_empty() {
            let suffix: Vec<String> = glyph_tones
                .iter()
                .filter_map(|t| tones.names.get(t).cloned())
                .collect();
            emojis[index].name = if suffix.is_empty() {
                base_name.clone()
            } else {
                format!("{}: {}", base_name, suffix.join(", "))
            };
        }

        let tone_en: Vec<&str> = glyph_tones
            .iter()
            .filter_map(|t| tones.en.get(t))
            .flatten()
            .map(|w| w.as_str())
            .collect();
        let tone_id: Vec<&str> = glyph_tones
            .iter()
            .filter_map(|t| tones.id.get(t))
            .flatten()
            .map(|w| w.as_str())
            .collect();

        emojis[index].keywords = merge_keywords(
            base_en
                .split_whitespace()
                .chain(extra_en.split_whitespace())
                .chain(tone_en),
        );
        emojis[index].keywords_id = merge_keywords(
            base_id
                .split_whitespace()
                .chain(extra_id.split_whitespace())
                .chain(tone_id),
        );
    }
}

fn codepoints_of(glyph: &str) -> String {
    let mut out = String::with_capacity(glyph.len() * 2);
    for ch in glyph.chars() {
        if !out.is_empty() {
            out.push(' ');
        }
        out.push_str(&format!("{:X}", ch as u32));
    }
    out
}

/// Accepts `1f44b`, `u+1f44b`, `0x1f44b`, or a space-separated sequence and
/// returns the concatenated uppercase hex form used for comparison.
fn hex_form(query: &str) -> Option<String> {
    let cleaned: String = query
        .chars()
        .filter(|c| !c.is_whitespace())
        .collect::<String>()
        .to_lowercase();
    let cleaned = cleaned
        .trim_start_matches("u+")
        .trim_start_matches("0x")
        .to_string();
    if !(2..=32).contains(&cleaned.len()) {
        return None;
    }
    if !cleaned.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    // Reject plain words such as "face" or "dead" that happen to be hex.
    if !cleaned.chars().any(|c| c.is_ascii_digit()) {
        return None;
    }
    Some(cleaned.to_uppercase())
}
